951:    * This method can be used to apply custom operations without breaking the “code flow”.
952:    * It works particularly well with method references.
953:    * <pre class="java">{@code
954:    * import ratpack.exec.Promise;
955:    * import ratpack.test.exec.ExecHarness;
956:    *
957:    * import static org.junit.Assert.assertEquals;
958:    *
959:    * public class Example {
960:    *   public static void main(String... args) throws Exception {
961:    *     Integer value = ExecHarness.yieldSingle(e ->
962:    *         Promise.value(1)
963:    *           .apply(Example::dubble)
964:    *           .apply(Example::triple)
965:    *     ).getValue();
966:    *
967:    *     assertEquals(Integer.valueOf(6), value);
968:    *   }
969:    *
970:    *   public static Promise<Integer> dubble(Promise<Integer> input) {
971:    *     return input.map(i -> i * 2);
972:    *   }
973:    *
974:    *   public static Promise<Integer> triple(Promise<Integer> input) {
