239:   /**
240:    * Specifies what should be done with the promised object when it becomes available.
241:    * <p>
242:    * <b>Important:</b> this method can only be used from a Ratpack managed compute thread.
243:    * If it is called on a non Ratpack managed compute thread it will immediately throw an {@link ExecutionException}.
244:    *
245:    * @param then the receiver of the promised value
246:    * @throws ExecutionException if not called on a Ratpack managed compute thread
247:    */
248:   void then(Action<? super T> then);
249: 
250:   /**
251:    * A low level hook for consuming the promised value.
252:    * <p>
253:    * It is generally preferable to use {@link #then(Action)} over this method.
254:    *
255:    * @param downstream the downstream consumer
256:    */
257:   void connect(Downstream<? super T> downstream);
