430:   /**
431:    * Transforms the promised value by applying the given function to it.
432:    * <pre class="java">{@code
433:    * import ratpack.test.exec.ExecHarness;
434:    * import ratpack.exec.ExecResult;
435:    * import ratpack.exec.Promise;
436:    *
437:    * import static org.junit.Assert.assertEquals;
438:    *
439:    * public class Example {
440:    *   public static void main(String... args) throws Exception {
441:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
442:    *         Promise.value("foo")
443:    *           .map(String::toUpperCase)
444:    *           .map(s -> s + "-BAR")
445:    *     );
446:    *
447:    *     assertEquals("FOO-BAR", result.getValue());
448:    *   }
449:    * }
450:    * }</pre>
451:    *
452:    * @param transformer the transformation to apply to the promised value
453:    * @param <O> the type of the transformed object
454:    * @return a promise for the transformed value
455:    */
