470:   /**
471:    * Transforms the promised value by applying the given function to it, if it satisfies the predicate.
472:    *
473:    * <pre class="java">{@code
474:    * import ratpack.test.exec.ExecHarness;
475:    * import ratpack.exec.ExecResult;
476:    * import ratpack.exec.Promise;
477:    *
478:    * import static org.junit.Assert.assertEquals;
479:    *
480:    * public class Example {
481:    *   public static void main(String... args) throws Exception {
482:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
483:    *         Promise.value("foo")
484:    *           .mapIf(s -> s.contains("f"), String::toUpperCase)
485:    *           .mapIf(s -> s.contains("f"), s -> s + "-BAR")
486:    *     );
487:    *
488:    *     assertEquals("FOO", result.getValue());
489:    *   }
490:    * }
491:    * }</pre>
492:    *
493:    * @param predicate the condition to satisfy in order to be transformed
494:    * @param transformer the transformation to apply to the promised value
495:    * @return a promise
496:    * @since 1.4
497:    */
498:   default Promise<T> mapIf(Predicate<? super T> predicate, Function<? super T, ? extends T> transformer) {
499:     return map(t -> predicate.apply(t) ? transformer.apply(t) : t);
500:   }
