549:    * The given action is executed within an {@link Operation}, allowing it to perform asynchronous work.
550:    *
551:    * <pre class="java">{@code
552:    * import ratpack.test.exec.ExecHarness;
553:    * import ratpack.exec.ExecResult;
554:    * import ratpack.exec.Promise;
555:    *
556:    * import com.google.common.collect.Lists;
557:    *
558:    * import java.util.concurrent.TimeUnit;
559:    * import java.util.Arrays;
560:    * import java.util.List;
561:    *
562:    * import static org.junit.Assert.assertEquals;
563:    *
564:    * public class Example {
565:    *   public static void main(String... args) throws Exception {
566:    *     List<String> events = Lists.newLinkedList();
567:    *     ExecHarness.runSingle(c ->
568:    *       Promise.value("foo")
569:    *        .next(v ->
570:    *          Promise.value(v) // may be async
571:    *            .map(String::toUpperCase)
572:    *            .then(events::add)
573:    *        )
574:    *        .then(events::add)
575:    *     );
576:    *     assertEquals(Arrays.asList("FOO", "foo"), events);
577:    *   }
578:    * }
579:    * }</pre>
