659:    * This method can be used when a subsequent operation on a promise isn't dependent on the actual promised value.
660:    * <p>
661:    * If the upstream promise fails, its error will propagate downstream and the given promise will never be subscribed to.
662:    *
663:    *  <pre class="java">{@code
664:    * import ratpack.test.exec.ExecHarness;
665:    * import ratpack.exec.ExecResult;
666:    * import ratpack.exec.Promise;
667:    *
668:    * import static org.junit.Assert.assertEquals;
669:    *
670:    * public class Example {
