43:     if (type == ExecType.BLOCKING) {
44:       String tag = buildBlockingTimerTag(request.getUri(), request.getMethod().getName());
45:       Timer.Context timer = metricRegistry.timer(tag).time();
46:       try {
47:         continuation.execute();
48:       } finally {
49:         timer.stop();
50:       }
51:     } else {
52:       continuation.execute();
53:     }
54:   }
